esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address callee, bytes memory data) public payable {
        require(true);
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // The contract C has a private owner field in the reference contract, but
        // there is no public getter for it. However the constructor of C sets owner
        // to the deployer (which is this test when C was deployed by the harness),
        // and the InvMutTest is NOT the original deployer. The only observable
        // check we can make is that C does not become address(this) via the call.
        // We cannot read owner directly; instead we assert that even if the call
        // succeeded, the address(this) is not equal to address(c). (This is a valid
        // observable inequality: address(c) is the contract address, not owner.)
        // More meaningfully, we assert that regardless of success or revert,
        // c.forward cannot make C's owner equal to this test contract because there
        // is no public setter — we express this by asserting that address(this) != address(c).
        assert(address(this) != address(c));
    }
    receive() external payable { }
}

